import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const at=file=>fileURLToPath(new URL(file,import.meta.url));
const startMark='          const parent_rule_count = rule_ids.length;';
const endMark='\n        }\n      }\n      continue;';
for(const driver of ['lookupbench','deepbench']){
 const js=readFileSync(at('base-'+driver+'.js'),'utf8').replaceAll('\r\n','\n');
 const start=js.indexOf(startMark);
 const end=js.indexOf(endMark,start);
 assert(start>=0&&end>start);
 const work=js.slice(start,end);
 const twoOrders=/const [^=\n]+ = \[\{ _0: _j, _1: _i \}, \{ _0: _i, _1: _j \}\];/;
 const push=/^( +).*push[^(]*\(stack, new .*PlanBranch\(parent_rule_count, \{ _0: _a, _1: _b \}\)\);$/m;
 assert(twoOrders.test(work)&&push.test(work));
 for(const mode of ['counts','push','timer-control']){
  const header="const stats={decisions:0,temporaryArrays:0,temporaryPairs:0,branchRecords:0,retainedPairs:0,peakPending:0,ms:0};\n"+
  "process.once('exit',()=>console.error(JSON.stringify(stats)));\n";
  const count=work.replace(twoOrders,'stats.decisions++; stats.temporaryArrays++; stats.temporaryPairs+=2;\n          $&')
    .replace(push,'$1stats.branchRecords++; stats.retainedPairs++;\n$&')+
    '\n          stats.peakPending=Math.max(stats.peakPending,stack.length);';
  const before='          const phaseStart=performance.now();\n';
  const after='          stats.ms+=performance.now()-phaseStart;';
  const measured=mode==='counts'?count:mode==='push'?before+work+'\n'+after:before+after+'\n'+work;
  writeFileSync(at('base-'+driver+'-'+mode+'.js'),header+js.slice(0,start)+measured+js.slice(end));
 }
}
const names=['maintenance','independent','first-pair','four-resources','one-resource','max-model','tight-impossible'];
const rows=[];
for(const name of names){
 const deep=name==='tight-impossible';
 const run=mode=>{
  const args=[at('base-'+(deep?'deepbench':'lookupbench')+'-'+mode+'.js'),...(deep?[]:[name])];
  const r=spawnSync(process.execPath,args,{encoding:'utf8',timeout:40000});
  assert.ifError(r.error);
  assert.equal(r.status,0,r.stderr);
  assert.equal(r.stdout.trim().split(/\r?\n/).length,9);
  return JSON.parse(r.stderr);
 };
 const {ms,...counts}=run('counts');
 assert.equal(counts.temporaryArrays,counts.decisions);
 for(const key of ['temporaryPairs','branchRecords','retainedPairs'])assert.equal(counts[key],2*counts.decisions);
 const times={push:[],'timer-control':[]};
 for(let i=0;i<3;i++){
  const modes=Object.keys(times);
  for(const mode of i%2?modes.reverse():modes)times[mode].push(run(mode).ms);
 }
 rows.push({name,counts,ms:times});
 console.log(name,counts.decisions,counts.peakPending,JSON.stringify(times));
}
writeFileSync(at('baseline-probe.json'),JSON.stringify(rows,null,2)+'\n');

