import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const at=file=>fileURLToPath(new URL(file,import.meta.url));
const profile=JSON.parse(readFileSync(at('baseline-probe.json'),'utf8'));
const startMark='          const parent_rule_count = rule_ids.length;';
const endMark='\n        }\n      }\n      continue;';
const results={};
for(const variant of ['direct','flat']){
 const rows={};
 for(const driver of ['lookupbench','deepbench']){
  const source=readFileSync(at(variant+'-'+driver+'.js'),'utf8').replaceAll('\r\n','\n');
  const a=source.indexOf(startMark), b=source.indexOf(endMark,a);
  assert(a>=0&&b>a);
  const region=source.slice(a,b);
  assert.equal(region.includes(' = ['),false);
  const pushes=region.match(/^ *.*push[^(]*\(stack, new .*PlanBranch\(parent_rule_count, .*$/gm);
  assert.equal(pushes.length,2);
  const pairs=pushes.filter(line=>line.includes('{ _0:')).length;
  assert.equal(pairs,variant==='direct'?2:0);
  const injected='          counts.decisions++;\n'+region.replaceAll(/^ *(.*push[^(]*\(stack, new .*PlanBranch.*)$/gm,
    line=>'          counts.branchRecords++;\n'+(pairs?'          counts.retainedPairs++;\n':'')+line)+
    '\n          counts.peakPending=Math.max(counts.peakPending,stack.length);';
  const header="const counts={decisions:0,temporaryArrays:0,temporaryPairs:0,branchRecords:0,retainedPairs:0,peakPending:0};\n"+
    "process.once('exit',()=>console.error(JSON.stringify(counts)));\n";
  const out=at(variant+'-'+driver+'-counts.js');
  writeFileSync(out,header+source.slice(0,a)+injected+source.slice(b));
  for(const row of profile.filter(row=>(row.name==='tight-impossible')===(driver==='deepbench'))){
   const args=[out,...(driver==='lookupbench'?[row.name]:[])];
   const r=spawnSync(process.execPath,args,{encoding:'utf8',timeout:30000});
   assert.ifError(r.error);
   assert.equal(r.status,0,r.stderr);
   assert.equal(r.stdout.trim().split(/\r?\n/).length,9);
   const counts=JSON.parse(r.stderr);
   for(const k of ['decisions','branchRecords','peakPending'])assert.equal(counts[k],row.counts[k]);
   assert.equal(counts.retainedPairs,row.counts.decisions*pairs);
   rows[row.name]=counts;
  }
 }
 results[variant]=rows;
}
for(const variant of Object.keys(results))console.log(variant,JSON.stringify(results[variant]['max-model']));
writeFileSync(at('variant-counts.json'),JSON.stringify(results,null,2)+'\n');

